import { z } from 'zod';
import { TIME_ZONES } from './timeZones.js';
import { TimeSchema } from './schedulesSchema.js';

export const TEMPERATURES = ['celsius', 'fahrenheit'] as const;
const Temperatures = z.enum(TEMPERATURES);


const TemperatureTapConfig = z.object({
  type: z.literal('temperature'),
  change: z.enum(['increment', 'decrement']),
  amount: z.number().min(0).max(10),
});

const PowerTapConfig = z.object({
  type: z.literal('power'),
  action: z.enum(['off', 'on', 'toggle']),
});

/** Copy current target temp into the active schedule slot for all days of the week */
const ScheduleApplyTapConfig = z.object({
  type: z.literal('scheduleApply'),
});

const AlarmTapConfig = z.object({
  type: z.literal('alarm'),
  behavior: z.enum(['snooze', 'dismiss']),
  snoozeDuration: z.number().min(60).max(600),
  inactiveAlarmBehavior: z.enum(['power', 'none'])
});

const NoneTapConfig = z.object({
  type: z.literal('none'),
});

export const TapConfig = z.discriminatedUnion('type', [
  TemperatureTapConfig,
  PowerTapConfig,
  ScheduleApplyTapConfig,
  AlarmTapConfig,
  NoneTapConfig,
]);

/** Multi-tap patterns reported by the Pod cover (Pod 4/5). Single-tap is not available over dac. */
export const GestureSchema = z.enum(['doubleTap', 'tripleTap', 'quadTap']);

/** Auto-run sleep analysis when this side powers off (schedule, GUI, or tap). */
const AnalyzeSleepSettingsSchema = z.object({
  enabled: z.boolean(),
  /** Skip analysis if the side was on for less than this many minutes */
  minDurationMinutes: z.number().int().min(0).max(24 * 60),
}).strict();

/** Beta: schedule-prior auto presence calibration for this side. */
const AutoPresenceCalibrationSchema = z.object({
  enabled: z.boolean(),
}).strict();

const SideSettingsSchema = z.object({
  name: z.string().min(1).max(20),
  awayMode: z.boolean(),
  analyzeSleep: AnalyzeSleepSettingsSchema,
  autoPresenceCalibration: AutoPresenceCalibrationSchema,
  scheduleOverrides: z.object({
    temperatureSchedules: z.object({
      disabled: z.boolean(),
      expiresAt: z.string(),
    }),
    alarm: z.object({
      disabled: z.boolean(),
      timeOverride: z.string(),
      expiresAt: z.string(),
    })
  }),
  taps: z.object({
    doubleTap: TapConfig,
    tripleTap: TapConfig,
    quadTap: TapConfig,
  })
}).strict();

/**
 * Reserved for future global beta flags.
 * Auto presence calibration lives per-side (left/right.autoPresenceCalibration).
 */
const BetaSettingsSchema = z.object({}).strict();

export const SettingsSchema = z.object({
  id: z.string(),
  timeZone: z.enum(TIME_ZONES),
  left: SideSettingsSchema,
  right: SideSettingsSchema,
  primePodDaily: z.object({
    enabled: z.boolean(),
    time: TimeSchema,
  }),
  temperatureFormat: Temperatures,
  rebootDaily: z.boolean(),
  beta: BetaSettingsSchema,
}).strict();

export type SideSettings = z.infer<typeof SideSettingsSchema>;
export type Settings = z.infer<typeof SettingsSchema>;
export type Gesture = z.infer<typeof GestureSchema>;
export type TapConfigType = z.infer<typeof TapConfig>;
